    equipOwned: { de: 'IM BESITZ', en: 'OWNED', fr: 'POSSÉDÉ', es: 'YA LO TIENES', ja: '所持', zh: '已拥有', it: 'IN POSSESSO', ro: 'DEȚINUT' },
    equipHelp: { de: '←→ WECHSELN  SPRUNG: TRINKEN  START: ZURÜCK', en: '←→ CHANGE  JUMP: DRINK  START: BACK', fr: '←→ CHANGER  SAUT : BOIRE  START : RETOUR', es: '←→ CAMBIAR  SALTO: BEBER  START: VOLVER', ja: '←→変更 ジャンプ:飲む START:戻る', zh: '←→更换 跳跃:喝 START:返回', it: '←→ CAMBIA  SALTO: BEVI  START: INDIETRO', ro: '←→ SCHIMBĂ  SALT: BEA  START: ÎNAPOI' },
