    shopTitle: { de: 'LADEN', en: 'SHOP', fr: 'BOUTIQUE', es: 'TIENDA', ja: '店', zh: '商店', it: 'NEGOZIO', ro: 'MAGAZIN' },
    shopHelp: { de: '↑↓ WÄHLEN  ←→ MODUS  SPRUNG: OK  START: GEHEN', en: '↑↓ SELECT  ←→ MODE  JUMP: OK  START: LEAVE', fr: '↑↓ CHOISIR  ←→ MODE  SAUT : OK  START : PARTIR', es: '↑↓ ELEGIR  ←→ MODO  SALTO: OK  START: SALIR', ja: '↑↓選択 ←→切替 ジャンプ:決定 START:出る', zh: '↑↓选择 ←→切换 跳跃:确定 START:离开', it: '↑↓ SCEGLI  ←→ MODO  SALTO: OK  START: ESCI', ro: '↑↓ ALEGE  ←→ MOD  SALT: OK  START: IEȘI' },
    shopHi: { de: 'ICH VERKAUFE AUCH. DER GRAF ZAHLT MIR SEIT 300 JAHREN KEIN GEHALT.', en: "I ALSO SELL THINGS. THE COUNT HASN'T PAID ME IN 300 YEARS.", fr: "JE VENDS AUSSI. LE COMTE NE ME PAIE PLUS DEPUIS 300 ANS.", es: 'TAMBIÉN VENDO. EL CONDE NO ME PAGA DESDE HACE 300 AÑOS.', ja: 'わしは店もやっておる。伯爵は300年も給料を払っておらんのでな。', zh: '我也卖东西。伯爵已经三百年没给我发工资了。', it: 'VENDO ANCHE COSE. IL CONTE NON MI PAGA DA 300 ANNI.', ro: 'VÂND ȘI EU. CONTELE NU MI-A MAI DAT SALARIUL DE 300 DE ANI.' },
    shopThanks1: { de: 'DANKE! ICH SPARE AUF EINE TOILETTE.', en: "THANK YOU! I'M SAVING UP FOR A TOILET.", fr: "MERCI ! J'ÉCONOMISE POUR DES TOILETTES.", es: '¡GRACIAS! AHORRO PARA UN BAÑO.', ja: 'ありがとう！トイレを買うために貯金中じゃ。', zh: '谢谢！我在攒钱修个厕所。', it: 'GRAZIE! STO RISPARMIANDO PER UN BAGNO.', ro: 'MULȚUMESC! STRÂNG BANI PENTRU O TOALETĂ.' },
    shopThanks2: { de: 'KEIN UMTAUSCH. KEINE GARANTIE. KEINE FRAGEN.', en: 'NO RETURNS. NO WARRANTY. NO QUESTIONS.', fr: 'NI REPRISE, NI GARANTIE, NI QUESTIONS.', es: 'SIN DEVOLUCIONES. SIN GARANTÍA. SIN PREGUNTAS.', ja: '返品不可。保証なし。質問もなし。', zh: '不退不换。没有保修。不许提问。', it: 'NIENTE RESI. NIENTE GARANZIA. NIENTE DOMANDE.', ro: 'NU SE RETURNEAZĂ. FĂRĂ GARANȚIE. FĂRĂ ÎNTREBĂRI.' },
    shopThanks3: { de: 'GUTE WAHL. DER LETZTE KÄUFER LEBT SOGAR NOCH.', en: 'GOOD CHOICE. THE LAST BUYER IS EVEN STILL ALIVE.', fr: 'BON CHOIX. LE DERNIER ACHETEUR EST MÊME ENCORE EN VIE.', es: 'BUENA ELECCIÓN. EL ÚLTIMO COMPRADOR INCLUSO SIGUE VIVO.', ja: 'いい選択じゃ。前の客はまだ生きておるぞ。', zh: '好眼光。上一个买家居然还活着。', it: "OTTIMA SCELTA. L'ULTIMO ACQUIRENTE È PERFINO ANCORA VIVO.", ro: 'BUNĂ ALEGERE. ULTIMUL CUMPĂRĂTOR CHIAR MAI TRĂIEȘTE.' },
