    famSay_fairy: { de: ['DU SCHAFFST DAS!', 'SAG WAS NETTES.', 'NICHT STERBEN, BITTE.', 'ICH BIN ÜBRIGENS WUNDERSCHÖN.'], en: ['YOU CAN DO IT!', 'SAY SOMETHING NICE.', "DON'T DIE, PLEASE.", "I'M GORGEOUS, BY THE WAY."], fr: ['TU PEUX LE FAIRE !', 'DIS UN TRUC GENTIL.', 'NE MEURS PAS, STP.', 'JE SUIS SUBLIME, AU FAIT.'], es: ['¡TÚ PUEDES!', 'DI ALGO BONITO.', 'NO TE MUERAS, PORFA.', 'POR CIERTO, SOY PRECIOSA.'], ja: ['がんばって！', '何かほめて。', '死なないでね。', 'ちなみに私、きれいでしょ。'], zh: ['你能行！', '说点好听的。', '拜托别死。', '顺便说一句，我很美。'], it: ['CE LA PUOI FARE!', 'DIMMI QUALCOSA DI CARINO.', 'NON MORIRE, TI PREGO.', "IO SONO BELLISSIMA, TRA L'ALTRO."], ro: ['POȚI S-O FACI!', 'ZI CEVA DRĂGUȚ.', 'NU MURI, TE ROG.', 'APROPO, SUNT SUPERBĂ.'] },
    famSay_tent: { de: ['WELTHERRSCHAFT!', 'ICH BIN NICHT KLEIN. ICH BIN KOMPAKT.', 'ONKEL SAGT HALLO.', 'SIND WIR BALD DA?', 'ICH HAB HUNGER. AUF MACHT.'], en: ['WORLD DOMINATION!', "I'M NOT SMALL. I'M COMPACT.", 'UNCLE SAYS HI.', 'ARE WE THERE YET?', "I'M HUNGRY. FOR POWER."], fr: ['DOMINATION MONDIALE !', 'PAS PETIT. COMPACT.', 'TONTON DIT BONJOUR.', 'ON ARRIVE BIENTÔT ?', "J'AI FAIM. DE POUVOIR."], es: ['¡DOMINACIÓN MUNDIAL!', 'NO SOY PEQUEÑO. SOY COMPACTO.', 'EL TÍO TE SALUDA.', '¿FALTA MUCHO?', 'TENGO HAMBRE. DE PODER.'], ja: ['世界征服！', '小さくない。コンパクトなんだ。', 'おじさんがよろしくって。', 'まだ着かないの？', 'おなかすいた。権力に。'], zh: ['征服世界！', '我不是小，我是紧凑。', '叔叔向你问好。', '还没到吗？', '我饿了。渴望权力。'], it: ['DOMINIO DEL MONDO!', 'NON SONO PICCOLO. SONO COMPATTO.', 'LO ZIO TI SALUTA.', 'SIAMO ARRIVATI?', 'HO FAME. DI POTERE.'], ro: ['DOMINAȚIE MONDIALĂ!', 'NU SUNT MIC. SUNT COMPACT.', 'UNCHIUL TE SALUTĂ.', 'MAI E MULT?', 'MI-E FOAME. DE PUTERE.'] },
    story_tent3: {
      de: ['T:DU HAST DIE FEDER! SCHÖN FÜR DICH. ICH HABE IMMER NOCH KEINE BEINE.', 'T:HÖR ZU. MEIN NEFFE WILL DIE WELT SEHEN. BEVOR WIR SIE EROBERN. NIMM IHN MIT.', 'H:... ER SIEHT AUS WIE DU. NUR KLEINER.', 'T:KOMPAKTER. ER HAUT ZU, WENN WAS KOMMT. UND ER REDET. VIEL. VIEL ZU VIEL.'],
      en: ['T:YOU GOT THE FEATHER! GOOD FOR YOU. I STILL HAVE NO LEGS.', 'T:LISTEN. MY NEPHEW WANTS TO SEE THE WORLD. BEFORE WE CONQUER IT. TAKE HIM WITH YOU.', 'H:... HE LOOKS LIKE YOU. ONLY SMALLER.', 'T:MORE COMPACT. HE SLAPS ANYTHING THAT COMES CLOSE. AND HE TALKS. A LOT. FAR TOO MUCH.'],
      fr: ["T:TU AS LA PLUME ! TANT MIEUX POUR TOI. MOI, JE N'AI TOUJOURS PAS DE JAMBES.", "T:ÉCOUTE. MON NEVEU VEUT VOIR LE MONDE. AVANT QU'ON LE CONQUIÈRE. EMMÈNE-LE.", 'H:... IL TE RESSEMBLE. EN PLUS PETIT.', 'T:EN PLUS COMPACT. IL FRAPPE CE QUI APPROCHE. ET IL PARLE. BEAUCOUP. BEAUCOUP TROP.'],
      es: ['T:¡TIENES LA PLUMA! ME ALEGRO POR TI. YO SIGO SIN PIERNAS.', 'T:ESCUCHA. MI SOBRINO QUIERE VER EL MUNDO. ANTES DE QUE LO CONQUISTEMOS. LLÉVATELO.', 'H:... SE PARECE A TI. PERO MÁS PEQUEÑO.', 'T:MÁS COMPACTO. GOLPEA LO QUE SE ACERCA. Y HABLA. MUCHO. DEMASIADO.'],
      ja: ['T:羽を手に入れたか！よかったな。オレ様はまだ足がない。', 'T:いいか。オレ様の甥が世界を見たいそうだ。征服する前にな。連れていけ。', 'H:……お前にそっくりだな。小さいだけで。', 'T:コンパクトなんだ。近づく奴はひっぱたく。それによくしゃべる。しゃべりすぎる。'],
      zh: ['T:你拿到羽毛了！恭喜。我还是没有腿。', 'T:听着。我侄子想看看世界。在我们征服它之前。带上他。', 'H:……他长得跟你一样。只是小一点。', 'T:是紧凑一点。谁靠近他就抽谁。而且他话很多。多得要命。'],
      it: ['T:HAI LA PIUMA! BUON PER TE. IO ANCORA NON HO LE GAMBE.', 'T:ASCOLTA. MIO NIPOTE VUOLE VEDERE IL MONDO. PRIMA CHE LO CONQUISTIAMO. PORTALO CON TE.', 'H:... TI SOMIGLIA. SOLO PIÙ PICCOLO.', 'T:PIÙ COMPATTO. SCHIAFFEGGIA TUTTO CIÒ CHE SI AVVICINA. E PARLA. TANTO. FIN TROPPO.'],
      ro: ['T:AI PANA! BRAVO ȚIE. EU TOT N-AM PICIOARE.', 'T:ASCULTĂ. NEPOTUL MEU VREA SĂ VADĂ LUMEA. ÎNAINTE S-O CUCERIM. IA-L CU TINE.', 'H:... SEAMĂNĂ CU TINE. DOAR CĂ E MAI MIC.', 'T:MAI COMPACT. PLESNEȘTE ORICE SE APROPIE. ȘI VORBEȘTE. MULT. MULT PREA MULT.'],
    },
    story_tent3Again: { de: 'PASS AUF MEINEN NEFFEN AUF. UND ER AUF DICH. DAS IST DER DEAL.', en: "LOOK AFTER MY NEPHEW. AND HE'LL LOOK AFTER YOU. THAT'S THE DEAL.", fr: "VEILLE SUR MON NEVEU. ET LUI SUR TOI. C'EST LE MARCHÉ.", es: 'CUIDA DE MI SOBRINO. Y ÉL CUIDARÁ DE TI. ESE ES EL TRATO.', ja: '甥を頼んだぞ。甥もお前を守る。そういう取引だ。', zh: '照顾好我侄子。他也会照顾你。这就是交易。', it: 'BADA A MIO NIPOTE. E LUI BADERÀ A TE. QUESTO È IL PATTO.', ro: 'AI GRIJĂ DE NEPOTUL MEU. ȘI EL ARE GRIJĂ DE TINE. ĂSTA E TÂRGUL.' },
