    story_conc1Again: { de: 'ZIMMER 13 IST LEIDER BELEGT. VON ETWAS MIT TENTAKELN. ES ZAHLT NICHT, ABER ES IST HÖFLICH.', en: 'ROOM 13 IS TAKEN, I AM AFRAID. BY SOMETHING WITH TENTACLES. IT DOES NOT PAY, BUT IT IS POLITE.', fr: 'LA CHAMBRE 13 EST OCCUPÉE, HÉLAS. PAR UNE CHOSE À TENTACULES. ELLE NE PAIE PAS, MAIS ELLE EST POLIE.', es: 'LA HABITACIÓN 13 ESTÁ OCUPADA. POR ALGO CON TENTÁCULOS. NO PAGA, PERO ES EDUCADO.', ja: '13号室はふさがっております。触手のある何かで。宿代は払いませんが、礼儀正しいのです。', zh: '13号房有人住了。是个长触手的东西。它不付钱，但很有礼貌。', it: 'LA CAMERA 13 È PURTROPPO OCCUPATA. DA QUALCOSA CON I TENTACOLI. NON PAGA, MA È EDUCATO.', ro: 'CAMERA 13 E DIN PĂCATE OCUPATĂ. DE CEVA CU TENTACULE. NU PLĂTEȘTE, DAR E POLITICOS.' },
    story_conc2Again: { de: 'DIE KLAPPE IST NUR FÜR HAUSTIERE. ↓ ↘ → UND SPRUNG, FALLS SIE EINES WERDEN MÖCHTEN.', en: 'THE FLAP IS FOR PETS ONLY. ↓ ↘ → AND JUMP, SHOULD YOU WISH TO BECOME ONE.', fr: 'LA CHATIÈRE EST RÉSERVÉE AUX ANIMAUX. ↓ ↘ → ET SAUT, SI VOUS SOUHAITEZ EN DEVENIR UN.', es: 'LA GATERA ES SOLO PARA MASCOTAS. ↓ ↘ → Y SALTO, SI DESEA SER UNA.', ja: 'その扉はペット専用です。なりたければ↓↘→とジャンプを。', zh: '那扇门只供宠物使用。想变成宠物的话，↓↘→加跳跃。', it: 'LA GATTAIOLA È SOLO PER ANIMALI DOMESTICI. ↓ ↘ → E SALTO, SE DESIDERA DIVENTARNE UNO.', ro: 'UȘIȚA E DOAR PENTRU ANIMALE DE COMPANIE. ↓ ↘ → ȘI SALT, DACĂ DORIȚI SĂ DEVENIȚI UNUL.' },
