    concThanks1: { de: 'EINE AUSGEZEICHNETE WAHL. DAS SAGE ICH BEI JEDER WAHL.', en: 'AN EXCELLENT CHOICE. I SAY THAT ABOUT EVERY CHOICE.', fr: 'UN EXCELLENT CHOIX. JE DIS CELA À CHAQUE CHOIX.', es: 'UNA ELECCIÓN EXCELENTE. LO DIGO DE TODAS.', ja: '素晴らしいお選びです。どれでもそう申しますが。', zh: '绝佳的选择。每个选择我都这么说。', it: 'UNA SCELTA ECCELLENTE. LO DICO DI OGNI SCELTA.', ro: 'O ALEGERE EXCELENTĂ. AȘA SPUN LA FIECARE ALEGERE.' },
    concThanks2: { de: 'BEEHREN SIE UNS BALD WIEDER. ODER ÜBERHAUPT.', en: 'DO VISIT US AGAIN SOON. OR AT ALL.', fr: 'REVENEZ BIENTÔT. OU REVENEZ TOUT COURT.', es: 'VUELVA PRONTO. O VUELVA, AL MENOS.', ja: 'またのお越しを。せめてもう一度。', zh: '欢迎早日再来。或者，至少再来一次。', it: 'TORNI PRESTO A TROVARCI. O ANCHE SOLO TORNI.', ro: 'VĂ MAI AȘTEPTĂM CURÂND. SAU MĂCAR VREODATĂ.' },
