    itemD_trident: { de: 'ATT +5. GABELT AUCH SPAGHETTI.', en: 'ATT +5. ALSO FORKS SPAGHETTI.', fr: 'ATT +5. PIQUE AUSSI LES SPAGHETTIS.', es: 'ATT +5. TAMBIÉN PINCHA ESPAGUETIS.', ja: 'ATT+5。スパゲッティも巻ける。', zh: 'ATT+5。还能叉意面。', it: 'ATT +5. INFILZA ANCHE GLI SPAGHETTI.', ro: 'ATT +5. ÎNFIGE ȘI SPAGHETE.' },
