    itemD_rec_kraken: { de: 'ACHT ARME, KEIN TAKTGEFÜHL.', en: 'EIGHT ARMS, NO SENSE OF RHYTHM.', fr: 'HUIT BRAS, AUCUN SENS DU RYTHME.', es: 'OCHO BRAZOS, NINGÚN RITMO.', ja: '腕は八本、リズム感はゼロ。', zh: '八条胳膊，毫无节奏感。', it: 'OTTO BRACCIA, ZERO SENSO DEL RITMO.', ro: 'OPT BRAȚE, ZERO SIMȚ AL RITMULUI.' },
    beast_Jelly: { de: 'QUALLE', en: 'JELLYFISH', fr: 'MÉDUSE', es: 'MEDUSA', ja: 'クラゲ', zh: '水母', it: 'MEDUSA MARINA', ro: 'MEDUZĂ DE MARE' },
    beastD_Jelly: { de: 'KEIN HERZ, KEIN HIRN, KEINE KNOCHEN. TROTZDEM GLÜCKLICH.', en: 'NO HEART, NO BRAIN, NO BONES. HAPPY ANYWAY.', fr: 'NI CŒUR, NI CERVEAU, NI OS. HEUREUSE QUAND MÊME.', es: 'SIN CORAZÓN, SIN CEREBRO, SIN HUESOS. FELIZ IGUAL.', ja: '心臓も脳も骨もない。それでも幸せ。', zh: '没有心、没有脑、没有骨头。照样快乐。', it: 'NIENTE CUORE, NIENTE CERVELLO, NIENTE OSSA. FELICE LO STESSO.', ro: 'FĂRĂ INIMĂ, FĂRĂ CREIER, FĂRĂ OASE. FERICITĂ ORICUM.' },
    story_diveAgain: { de: 'VERSUNKENE KAPELLE: LOCH AM ANFANG DES KANALS. HELM AUF, LUFT ANHALTEN. ODER AUCH NICHT.', en: 'SUNKEN CHAPEL: HOLE AT THE START OF THE CANAL. HELMET ON, HOLD YOUR BREATH. OR DON’T.', fr: 'CHAPELLE ENGLOUTIE : TROU AU DÉBUT DU CANAL. CASQUE, ET RETIENS TON SOUFFLE. OU PAS.', es: 'CAPILLA HUNDIDA: AGUJERO AL INICIO DEL CANAL. CASCO PUESTO Y AGUANTA LA RESPIRACIÓN. O NO.', ja: '沈んだ礼拝堂：水路の入口の穴だ。ヘルメットをかぶって息を止めろ。止めなくてもいい。', zh: '沉没礼拜堂：水道入口的洞。戴上头盔，憋住气。不憋也行。', it: "CAPPELLA SOMMERSA: BUCO ALL'INIZIO DEL CANALE. ELMO IN TESTA, TRATTIENI IL FIATO. O ANCHE NO.", ro: 'CAPELA SCUFUNDATĂ: GAURA DE LA ÎNCEPUTUL CANALULUI. CASCA PE CAP, ȚINE-ȚI RESPIRAȚIA. SAU NU.' },
    story_dive: {
      de: ['A:EIN TAUCHERHELM! JETZT KANNST DU SCHWIMMEN. IM WASSER IST JEDER SPRUNG EIN SCHWIMMZUG.', 'A:AM ANFANG DES KANALS GEHT EIN LOCH NACH UNTEN. DARUNTER LIEGT EINE VERSUNKENE KAPELLE. MIT GLOCKE. SIE LÄUTET NICHT MEHR. SIE BLUBBERT.'],
      en: ['A:A DIVING HELMET! NOW YOU CAN SWIM. UNDERWATER, EVERY JUMP IS A STROKE.', 'A:AT THE START OF THE CANAL A HOLE LEADS DOWN. BELOW LIES A SUNKEN CHAPEL. WITH A BELL. IT DOES NOT RING ANYMORE. IT BUBBLES.'],
      fr: ['A:UN CASQUE DE SCAPHANDRIER ! TU PEUX NAGER. SOUS L’EAU, CHAQUE SAUT EST UNE BRASSE.', 'A:AU DÉBUT DU CANAL, UN TROU DESCEND. EN DESSOUS, UNE CHAPELLE ENGLOUTIE. AVEC UNE CLOCHE. ELLE NE SONNE PLUS. ELLE FAIT DES BULLES.'],
      es: ['A:¡UN CASCO DE BUZO! AHORA PUEDES NADAR. BAJO EL AGUA, CADA SALTO ES UNA BRAZADA.', 'A:AL INICIO DEL CANAL UN AGUJERO BAJA. DEBAJO HAY UNA CAPILLA HUNDIDA. CON CAMPANA. YA NO SUENA. HACE BURBUJAS.'],
      ja: ['A:潜水ヘルメットか！これで泳げる。水中ではジャンプがひとかきになる。', 'A:水路の入口に下へ続く穴がある。その下に沈んだ礼拝堂がある。鐘もある。もう鳴らない。泡を吹く。'],
      zh: ['A:潜水头盔！现在你能游泳了。在水里，每次跳跃都是一次划水。', 'A:水道入口有个往下的洞。下面是一座沉没的礼拜堂。还有一口钟。它不再响了。它冒泡。'],
      it: ["A:UN ELMO DA PALOMBARO! ORA PUOI NUOTARE. SOTT'ACQUA OGNI SALTO È UNA BRACCIATA.", "A:ALL'INIZIO DEL CANALE UN BUCO PORTA GIÙ. SOTTO C'È UNA CAPPELLA SOMMERSA. CON UNA CAMPANA. NON SUONA PIÙ. FA LE BOLLE."],
      ro: ['A:O CASCĂ DE SCAFANDRU! ACUM POȚI ÎNOTA. SUB APĂ, FIECARE SALT E O MIȘCARE DE ÎNOT.', 'A:LA ÎNCEPUTUL CANALULUI O GAURĂ DUCE ÎN JOS. DEDESUBT E O CAPELĂ SCUFUNDATĂ. CU UN CLOPOT. NU MAI BATE. FACE BULE.'],
    },
    // Kaleidoskop: Prismenklinge, Wirbel gegen Verwandlungen
    item_prisma: { de: 'PRISMENKLINGE', en: 'PRISM BLADE', fr: 'LAME PRISMATIQUE', es: 'HOJA PRISMÁTICA', ja: 'プリズムの刃', zh: '棱镜之刃', it: 'LAMA PRISMATICA', ro: 'LAMA PRISMEI' },
