    motoMedal_gold: { de: '{0} S - GOLD! DER PRÜFMEISTER FÄLLT IN OHNMACHT. ER IST AUS BLECH, ES SCHEPPERT.', en: '{0} S - GOLD! THE INSPECTOR FAINTS. HE IS MADE OF TIN, IT CLANGS.', fr: "{0} S - OR ! L'INSPECTEUR S'ÉVANOUIT. IL EST EN FER-BLANC, ÇA FAIT UN BOUCAN.", es: '{0} S - ¡ORO! EL INSPECTOR SE DESMAYA. ES DE HOJALATA, HACE UN ESTRUENDO.', ja: '{0}秒 - 金！検査官が気絶。ブリキ製なのでガシャンと鳴る。', zh: '{0}秒 - 金牌！检验员晕倒了。他是铁皮做的，哐当一声。', it: "{0} S - ORO! L'ISPETTORE SVIENE. È DI LATTA, FA UN GRAN FRACASSO.", ro: '{0} S - AUR! INSPECTORUL LEȘINĂ. E DIN TABLĂ, ZDRĂNGĂNE.' },
    motoMedal_silver: { de: '{0} S - SILBER! DER PRÜFMEISTER NICKT ZWEIMAL. DAS IST SEIN HÖCHSTES LOB.', en: '{0} S - SILVER! THE INSPECTOR NODS TWICE. HIS HIGHEST PRAISE.', fr: "{0} S - ARGENT ! L'INSPECTEUR HOCHE DEUX FOIS LA TÊTE. SON PLUS GRAND ÉLOGE.", es: '{0} S - ¡PLATA! EL INSPECTOR ASIENTE DOS VECES. SU MAYOR ELOGIO.', ja: '{0}秒 - 銀！検査官が二度うなずいた。最大の賛辞だ。', zh: '{0}秒 - 银牌！检验员点了两次头。这是他最高的赞美。', it: "{0} S - ARGENTO! L'ISPETTORE ANNUISCE DUE VOLTE. LA SUA LODE PIÙ ALTA.", ro: '{0} S - ARGINT! INSPECTORUL DĂ DIN CAP DE DOUĂ ORI. CEA MAI MARE LAUDĂ A LUI.' },
    motoMedal_bronze: { de: '{0} S - BRONZE. DER PRÜFMEISTER NICKT. EINMAL.', en: '{0} S - BRONZE. THE INSPECTOR NODS. ONCE.', fr: "{0} S - BRONZE. L'INSPECTEUR HOCHE LA TÊTE. UNE FOIS.", es: '{0} S - BRONCE. EL INSPECTOR ASIENTE. UNA VEZ.', ja: '{0}秒 - 銅。検査官がうなずいた。一度だけ。', zh: '{0}秒 - 铜牌。检验员点了点头。就一次。', it: "{0} S - BRONZO. L'ISPETTORE ANNUISCE. UNA VOLTA.", ro: '{0} S - BRONZ. INSPECTORUL DĂ DIN CAP. O DATĂ.' },
    motoNoMedal: { de: '{0} S. DER PRÜFMEISTER GÄHNT. AUTOMATEN GÄHNEN NICHT. ER SCHON.', en: '{0} S. THE INSPECTOR YAWNS. AUTOMATONS DO NOT YAWN. HE DOES.', fr: "{0} S. L'INSPECTEUR BÂILLE. LES AUTOMATES NE BÂILLENT PAS. LUI, SI.", es: '{0} S. EL INSPECTOR BOSTEZA. LOS AUTÓMATAS NO BOSTEZAN. ÉL SÍ.', ja: '{0}秒。検査官があくび。自動人形はあくびしない。彼はする。', zh: '{0}秒。检验员打了个哈欠。自动人偶不打哈欠。他打。', it: "{0} S. L'ISPETTORE SBADIGLIA. GLI AUTOMI NON SBADIGLIANO. LUI SÌ.", ro: '{0} S. INSPECTORUL CASCĂ. AUTOMATELE NU CASCĂ. EL DA.' },
