    chgLab: { de: 'ERWECKTER: PLATEAUSTIEFEL, FUNKENBOLZEN', en: 'AWAKENED: PLATFORM BOOTS, SPARKING BOLTS', fr: 'ÉVEILLÉ : BOTTES COMPENSÉES, BOULONS', es: 'DESPERTADO: BOTAS DE PLATAFORMA, PERNOS', ja: '目覚めし者：厚底ブーツ・火花ボルト', zh: '苏醒者：厚底靴、冒火花的螺栓', it: 'RISVEGLIATO: STIVALI CON ZEPPA, BULLONI SCINTILLANTI', ro: 'CEL TREZIT: CIZME CU PLATFORMĂ, BULOANE CU SCÂNTEI' },
    chgPortrait: { de: 'AHNENBILDER MIT LEUCHTE UND NAMENSSCHILD', en: 'ANCESTOR PORTRAITS WITH LAMP AND NAMEPLATE', fr: 'PORTRAITS AVEC LAMPE ET PLAQUE', es: 'RETRATOS CON LÁMPARA Y PLACA', ja: '照明と名札付きの先祖の肖像画', zh: '带画灯和铭牌的祖先肖像', it: 'RITRATTI DI ANTENATI CON LAMPADA E TARGHETTA', ro: 'PORTRETE DE STRĂMOȘI CU LAMPĂ ȘI PLĂCUȚĂ' },
