    // ---------------- Gesprochene Zeilen (Text für die Browser-Stimme, falls keine Aufnahme vorliegt) ----------------
    'v.title': { de: 'Nachtmahr. Der Blutmond erwacht.', en: 'Nachtmahr. The blood moon awakens.', fr: "Nachtmahr. La lune de sang s'éveille.", es: 'Nachtmahr. La luna de sangre despierta.', ja: 'ナハトマール。血の月が目覚める。', zh: '纳赫特马尔。血月苏醒。', it: 'Nachtmahr. La luna di sangue si risveglia.', ro: 'Nachtmahr. Luna de sânge se trezește.' },
    'v.intro': { de: 'Anno 1691. Alle hundert Jahre erwacht Graf Nachtmahr unter dem Blutmond.', en: 'Anno 1691. Every hundred years, Count Nachtmahr rises beneath the blood moon.', fr: 'An de grâce 1691. Tous les cent ans, le comte Nachtmahr se lève sous la lune de sang.', es: 'Año 1691. Cada cien años, el conde Nachtmahr despierta bajo la luna de sangre.', ja: '1691年。百年に一度、血の月の下でナハトマール伯爵が蘇る。', zh: '公元1691年。每隔一百年，纳赫特马尔伯爵便会在血月之下苏醒。', it: 'Anno 1691. Ogni cento anni, il conte Nachtmahr risorge sotto la luna di sangue.', ro: 'Anul 1691. La fiecare sută de ani, contele Nachtmahr se trezește sub luna de sânge.' },
    'v.kaspar': { de: 'Kaspar, die Marionette ohne Fäden, schnitt sich von seinem Puppenspieler los und greift zur Hellebarde.', en: 'Kaspar, the puppet without strings, cut himself free from his puppeteer and takes up the halberd.', fr: "Kaspar, le pantin sans fils, s'est libéré de son marionnettiste et saisit la hallebarde.", es: 'Kaspar, la marioneta sin hilos, se soltó de su titiritero y empuña la alabarda.', ja: '糸の切れた人形カスパーは、人形遣いから自らを解き放ち、ハルバードを手に取る。', zh: '断线的木偶卡斯帕尔挣脱了操偶师的束缚，握起了长戟。', it: "Kaspar, la marionetta senza fili, si è liberato dal suo burattinaio e impugna l'alabarda.", ro: 'Kaspar, marioneta fără sfori, s-a desprins de păpușarul său și pune mâna pe halebardă.' },
    'v.henrik': { de: 'Henrik Morgenstern ergreift die Peitsche seiner Ahnen und betritt die verfluchte Burg.', en: 'Henrik Morgenstern takes up the whip of his ancestors and enters the cursed castle.', fr: 'Henrik Morgenstern saisit le fouet de ses ancêtres et pénètre dans le château maudit.', es: 'Henrik Morgenstern empuña el látigo de sus ancestros y entra en el castillo maldito.', ja: 'ヘンリク・モルゲンシュテルンは祖先の鞭を手に、呪われた城へ踏み込む。', zh: '亨里克·摩根施特恩手握祖传之鞭，踏入被诅咒的城堡。', it: 'Henrik Morgenstern impugna la frusta dei suoi avi ed entra nel castello maledetto.', ro: 'Henrik Morgenstern apucă biciul strămoșilor săi și intră în castelul blestemat.' },
